import{_ as t,a0 as o,w as d,s as r,ao as l,I as i,a1 as e,A as p,x as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何强制用户在下次登录 Linux 时更改密码 | LCTT x X-CMD","titleTemplate":false,"description":"如何强制用户在下次登录 Linux 时更改密码 | LCTT (201807) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何强制用户在下次登录 Linux 时更改密码 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何强制用户在下次登录 Linux 时更改密码 | LCTT (201807) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201807/20180718 How To Force User To Change Password On Next Login In Linux","title":"如何强制用户在下次登录 Linux 时更改密码","tag":"201807","desc":""},"relativePath":"201807/20180718 How To Force User To Change Password On Next Login In Linux.md","filePath":"[post].md"}'),h={name:"201807/20180718 How To Force User To Change Password On Next Login In Linux.md"};function u(c,s,g,w,k,m){const n=o("Link");return d(),r("div",null,[s[19]||(s[19]=l('<h1 id="如何强制用户在下次登录-linux-时更改密码" tabindex="-1">如何强制用户在下次登录 Linux 时更改密码 <a class="header-anchor" href="#如何强制用户在下次登录-linux-时更改密码" aria-label="Permalink to “如何强制用户在下次登录 Linux 时更改密码”">​</a></h1><p>当你使用默认密码创建用户时，你必须强制用户在下一次登录时更改密码。</p><p>当你在一个组织中工作时，此选项是强制性的。因为老员工可能知道默认密码，他们可能会也可能不会尝试不当行为。</p><p>这是安全投诉之一，所以，确保你必须以正确的方式处理此事而无任何失误。即使是你的团队成员也要一样做。</p><p>大多数用户都很懒，除非你强迫他们更改密码，否则他们不会这样做。所以要做这个实践。</p><p>出于安全原因，你需要经常更改密码，或者至少每个月更换一次。</p><p>确保你使用的是难以猜测的密码（大小写字母，数字和特殊字符的组合）。它至少应该为 10-15 个字符。</p><p>我们运行了一个 shell 脚本来在 Linux 服务器中创建一个用户账户，它会自动为用户附加一个密码，密码是实际用户名和少量数字的组合。</p><p>我们可以通过使用以下两种方法来实现这一点：</p><ul><li>passwd 命令</li><li>chage 命令</li></ul><p><strong>建议阅读：</strong></p>',11)),i("ul",null,[i("li",null,[e(n,{href:"https://www.2daygeek.com/how-to-check-which-groups-a-user-belongs-to-on-linux/"},{default:p(()=>[...s[0]||(s[0]=[a("如何在 Linux 上检查用户所属的组",-1)])]),_:1})]),i("li",null,[e(n,{href:"https://www.2daygeek.com/how-to-check-user-created-date-on-linux/"},{default:p(()=>[...s[1]||(s[1]=[a("如何在 Linux 上检查创建用户的日期",-1)])]),_:1})]),i("li",null,[e(n,{href:"https://www.2daygeek.com/passwd-command-examples/"},{default:p(()=>[...s[2]||(s[2]=[a("如何在 Linux 中重置/更改用户密码",-1)])]),_:1})]),i("li",null,[e(n,{href:"https://www.2daygeek.com/passwd-command-examples-part-l/"},{default:p(()=>[...s[3]||(s[3]=[a("如何使用 passwd 命令管理密码过期和老化",-1)])]),_:1})])]),s[20]||(s[20]=l(`<h3 id="方法-1-使用-passwd-命令" tabindex="-1">方法 1：使用 passwd 命令 <a class="header-anchor" href="#方法-1-使用-passwd-命令" aria-label="Permalink to “方法 1：使用 passwd 命令”">​</a></h3><p><code>passwd</code> 的意思是“密码”。它用于更新用户的身份验证令牌。<code>passwd</code> 命令/实用程序用于设置、修改或更改用户的密码。</p><p>普通的用户只能更改自己的账户，但超级用户可以更改任何账户的密码。</p><p>此外，我们还可以使用其他选项，允许用户执行其他活动，例如删除用户密码、锁定或解锁用户账户、设置用户账户的密码过期时间等。</p><p>在 Linux 中这可以通过调用 Linux-PAM 和 Libuser API 执行。</p><p>在 Linux 中创建用户时，用户详细信息将存储在 <code>/etc/passwd</code> 文件中。<code>passwd</code> 文件将每个用户的详细信息保存为带有七个字段的单行。</p><p>此外，在 Linux 系统中创建新用户时，将更新以下四个文件。</p><ul><li><code>/etc/passwd</code>： 用户详细信息将在此文件中更新。</li><li><code>/etc/shadow</code>： 用户密码信息将在此文件中更新。</li><li><code>/etc/group</code>： 新用户的组详细信息将在此文件中更新。</li><li><code>/etc/gshadow</code>： 新用户的组密码信息将在此文件中更新。</li></ul><h4 id="如何使用-passwd-命令执行此操作" tabindex="-1">如何使用 passwd 命令执行此操作 <a class="header-anchor" href="#如何使用-passwd-命令执行此操作" aria-label="Permalink to “如何使用 passwd 命令执行此操作”">​</a></h4><p>我们可以使用 <code>passwd</code> 命令并添加 <code>-e</code> 选项来执行此操作。</p><p>为了测试这一点，让我们创建一个新用户账户，看看它是如何工作的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># useradd -c &quot;2g Admin - Magesh M&quot; magesh &amp;&amp; passwd magesh</span></span>
<span class="line"><span>Changing password for user magesh.</span></span>
<span class="line"><span>New password:</span></span>
<span class="line"><span>Retype new password:</span></span>
<span class="line"><span>passwd: all authentication tokens updated successfully.</span></span></code></pre></div><p>使用户账户的密码失效，那么在下次登录尝试期间，用户将被迫更改密码。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># passwd -e magesh</span></span>
<span class="line"><span>Expiring password for user magesh.</span></span>
<span class="line"><span>passwd: Success</span></span></code></pre></div><p>当我第一次尝试使用此用户登录系统时，它要求我设置一个新密码。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>login as: magesh</span></span>
<span class="line"><span>[email protected]&#39;s password:</span></span>
<span class="line"><span>You are required to change your password immediately (root enforced)</span></span>
<span class="line"><span>WARNING: Your password has expired.</span></span>
<span class="line"><span>You must change your password now and login again!</span></span>
<span class="line"><span>Changing password for user magesh.</span></span>
<span class="line"><span>Changing password for magesh.</span></span>
<span class="line"><span>(current) UNIX password:</span></span>
<span class="line"><span>New password:</span></span>
<span class="line"><span>Retype new password:</span></span>
<span class="line"><span>passwd: all authentication tokens updated successfully.</span></span>
<span class="line"><span>Connection to localhost closed.</span></span></code></pre></div><h3 id="方法-2-使用-chage-命令" tabindex="-1">方法 2：使用 chage 命令 <a class="header-anchor" href="#方法-2-使用-chage-命令" aria-label="Permalink to “方法 2：使用 chage 命令”">​</a></h3><p><code>chage</code> 意即“改变时间”。它会更改用户密码过期信息。</p><p><code>chage</code> 命令会改变上次密码更改日期之后需要修改密码的天数。系统使用此信息来确定用户何时必须更改他/她的密码。</p><p>它允许用户执行其他活动，例如设置帐户到期日期，到期后设置密码失效，显示帐户过期信息，设置密码更改前的最小和最大天数以及设置到期警告天数。</p><h4 id="如何使用-chage-命令执行此操作" tabindex="-1">如何使用 chage 命令执行此操作 <a class="header-anchor" href="#如何使用-chage-命令执行此操作" aria-label="Permalink to “如何使用 chage 命令执行此操作”">​</a></h4><p>让我们在 <code>chage</code> 命令的帮助下，通过添加 <code>-d</code> 选项执行此操作。</p><p>为了测试这一点，让我们创建一个新用户帐户，看看它是如何工作的。我们将创建一个名为 <code>thanu</code> 的用户帐户。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># useradd -c &quot;2g Editor - Thanisha M&quot; thanu &amp;&amp; passwd thanu</span></span>
<span class="line"><span>Changing password for user thanu.</span></span>
<span class="line"><span>New password:</span></span>
<span class="line"><span>Retype new password:</span></span>
<span class="line"><span>passwd: all authentication tokens updated successfully.</span></span></code></pre></div><p>要实现这一点，请使用 <code>chage</code> 命令将用户的上次密码更改日期设置为 0。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># chage -d 0 thanu</span></span>
<span class="line"><span></span></span>
<span class="line"><span># chage -l thanu</span></span>
<span class="line"><span>Last password change : Jul 18, 2018</span></span>
<span class="line"><span>Password expires : never</span></span>
<span class="line"><span>Password inactive : never</span></span>
<span class="line"><span>Account expires : never</span></span>
<span class="line"><span>Minimum number of days between password change : 0</span></span>
<span class="line"><span>Maximum number of days between password change : 99999</span></span>
<span class="line"><span>Number of days of warning before password expires : 7</span></span></code></pre></div><p>当我第一次尝试使用此用户登录系统时，它要求我设置一个新密码。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>login as: thanu</span></span>
<span class="line"><span>[email protected]&#39;s password:</span></span>
<span class="line"><span>You are required to change your password immediately (root enforced)</span></span>
<span class="line"><span>WARNING: Your password has expired.</span></span>
<span class="line"><span>You must change your password now and login again!</span></span>
<span class="line"><span>Changing password for user thanu.</span></span>
<span class="line"><span>Changing password for thanu.</span></span>
<span class="line"><span>(current) UNIX password:</span></span>
<span class="line"><span>New password:</span></span>
<span class="line"><span>Retype new password:</span></span>
<span class="line"><span>passwd: all authentication tokens updated successfully.</span></span>
<span class="line"><span>Connection to localhost closed.</span></span></code></pre></div><hr>`,29)),i("p",null,[s[5]||(s[5]=a("via: ",-1)),e(n,{href:"https://www.2daygeek.com/how-to-force-user-to-change-password-on-next-login-in-linux/"},{default:p(()=>[...s[4]||(s[4]=[a("https://www.2daygeek.com/how-to-force-user-to-change-password-on-next-login-in-linux/",-1)])]),_:1})]),i("p",null,[s[10]||(s[10]=a("作者：",-1)),e(n,{href:"https://www.2daygeek.com/author/prakash/"},{default:p(()=>[...s[6]||(s[6]=[a("Prakash Subramanian",-1)])]),_:1}),s[11]||(s[11]=a(" 选题：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[7]||(s[7]=[a("lujun9972",-1)])]),_:1}),s[12]||(s[12]=a(" 译者：",-1)),e(n,{href:"https://github.com/MjSeven"},{default:p(()=>[...s[8]||(s[8]=[a("MjSeven",-1)])]),_:1}),s[13]||(s[13]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[9]||(s[9]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[16]||(s[16]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[14]||(s[14]=[a("LCTT",-1)])]),_:1}),s[17]||(s[17]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...s[15]||(s[15]=[a("Linux中国",-1)])]),_:1}),s[18]||(s[18]=a(" 荣誉推出",-1))])])}const y=t(h,[["render",u]]);export{x as __pageData,y as default};
